export function translateUi(language: SupportedLanguage, source: string): string {
  if (language === "en") return source;
  const exact = uiTranslations[language][source];
  if (exact) return exact;

  // Counts and filenames are assembled at runtime, so they cannot be plain
  // dictionary keys. Keep the grammar here rather than leaving fragments in
  // English when a user changes language.
  const activeItems = source.match(/^(\d+) active items?$/);
  if (activeItems) return language === "pt" ? `${activeItems[1]} ${activeItems[1] === "1" ? "item ativo" : "itens ativos"}` : `${activeItems[1]} ${activeItems[1] === "1" ? "elemento activo" : "elementos activos"}`;
  const attentionItems = source.match(/^(\d+) items? need attention$/);
  if (attentionItems) return language === "pt"
    ? `${attentionItems[1]} ${attentionItems[1] === "1" ? "item precisa de atenção" : "itens precisam de atenção"}`
    : `${attentionItems[1]} ${attentionItems[1] === "1" ? "elemento necesita atención" : "elementos necesitan atención"}`;
  const recordUpdate = source.match(/^Add an update to (.+)$/);
  if (recordUpdate) return language === "pt" ? `Adicionar uma atualização a ${recordUpdate[1]}` : `Añadir una actualización a ${recordUpdate[1]}`;
  const statusFor = source.match(/^Status for (.+)$/);
  if (statusFor) return language === "pt" ? `Status de ${statusFor[1]}` : `Estado de ${statusFor[1]}`;
  const recordItems = source.match(/^(\d+) record items? at this point$/);
  if (recordItems) return language === "pt"
    ? `${recordItems[1]} ${recordItems[1] === "1" ? "item no registro neste momento" : "itens no registro neste momento"}`
    : `${recordItems[1]} ${recordItems[1] === "1" ? "elemento en el registro en este momento" : "elementos en el registro en este momento"}`;
  const workspaceEmpty = source.match(/^When an authorised child is shared and a team member adds a (.+), it will appear here\.$/);
  if (workspaceEmpty) {
    const noun = translateUi(language, workspaceEmpty[1]);
    return language === "pt" ? `Quando uma criança autorizada for compartilhada e alguém da equipe adicionar ${noun}, ele aparecerá aqui.` : `Cuando se comparta un niño/a autorizado/a y alguien del equipo añada ${noun}, aparecerá aquí.`;
  }
  const workspaceCreate = source.match(/^This creates an operational (.+) linked to the authorised child record\. The record remains the source of truth\.$/);
  if (workspaceCreate) {
    const noun = translateUi(language, workspaceCreate[1]);
    return language === "pt" ? `Isso cria ${noun} operacional vinculado ao registro autorizado da criança. O registro continua sendo a fonte principal de informação.` : `Esto crea ${noun} operativo vinculado al registro autorizado del niño/a. El registro sigue siendo la fuente principal de información.`;
  }
  const readOnlyWorkspace = source.match(/^Your access is read-only\. Ask the child’s access administrator if you need permission to add or update (.+)s\.$/);
  if (readOnlyWorkspace) return language === "pt"
    ? "Seu acesso é somente leitura. Peça permissão ao administrador de acesso da criança para adicionar ou atualizar itens desta área."
    : "Tu acceso es de solo lectura. Pide permiso al administrador de acceso del niño/a para añadir o actualizar elementos de esta área.";
  const reviewRows = source.match(/^(\d+) of (\d+) rows are ready\. Dates must use YYYY-MM-DD; an empty date is allowed\.$/);
  if (reviewRows) return language === "pt"
    ? `${reviewRows[1]} de ${reviewRows[2]} linhas estão prontas. As datas devem usar AAAA-MM-DD; a data pode ficar em branco.`
    : `${reviewRows[1]} de ${reviewRows[2]} filas están listas. Las fechas deben usar AAAA-MM-DD; la fecha puede dejarse vacía.`;
  const reviewFile = source.match(/^Review (.+)$/);
  if (reviewFile) return language === "pt" ? `Revisar ${reviewFile[1]}` : `Revisar ${reviewFile[1]}`;
  const importConfirmation = source.match(/^This will create (\d+) pupil records? in this verified school workspace\. Existing matching names and dates of birth will be skipped\.$/);
  if (importConfirmation) return language === "pt"
    ? `Isso criará ${importConfirmation[1]} ${importConfirmation[1] === "1" ? "registro de aluno" : "registros de alunos"} nesta área escolar verificada. Nomes e datas de nascimento correspondentes já existentes serão ignorados.`
    : `Esto creará ${importConfirmation[1]} ${importConfirmation[1] === "1" ? "registro de alumno" : "registros de alumnos"} en esta área escolar verificada. Se omitirán nombres y fechas de nacimiento coincidentes existentes.`;
  const importResult = source.match(/^(\d+) pupil records? (was|were) added securely\. (\d+) duplicates? (was|were) skipped and (\d+) rows? (was|were) rejected\.$/);
  if (importResult) return language === "pt"
    ? `${importResult[1]} registros de alunos foram adicionados com segurança. ${importResult[3]} duplicados foram ignorados e ${importResult[5]} linhas foram rejeitadas.`
    : `${importResult[1]} registros de alumnos se añadieron de forma segura. Se omitieron ${importResult[3]} duplicados y se rechazaron ${importResult[5]} filas.`;
  return source;
}
